import { NextResponse } from 'next/server'
import { addItem, markBinned, markUsed, saveReceipt, updateExpiry } from '@/app/actions'
import { getHousehold } from '@/lib/household'
import { listItems } from '@/lib/items'
import { SAMPLE_LINES } from '@/lib/sample-lines'

export const dynamic = 'force-dynamic'

/**
 * Dev-only: walks every database action through the real Next runtime (cookies included)
 * for the household of the calling browser. 404 in production.
 */
export async function GET() {
  if (process.env.NODE_ENV === 'production') return new NextResponse(null, { status: 404 })
  const log: Record<string, unknown> = {}

  log.add = await addItem({ name: 'Selftest milk', qty: 1, unit: '1L', category: 'dairy', expiresOn: '2026-10-20' })
  const h1 = await getHousehold()
  log.household = h1 ? 'found' : 'missing'
  if (!h1) return NextResponse.json(log, { status: 500 })

  let items = await listItems(h1.id)
  const milk = items.find((i) => i.name === 'Selftest milk')
  log.afterAdd = { count: items.length, milk: milk ? { freshness: milk.freshness, daysLeft: milk.daysLeft, icon: milk.icon } : null }

  const key = crypto.randomUUID()
  log.save1 = await saveReceipt({ source: 'sample', clientKey: key, lines: SAMPLE_LINES })
  log.save2 = await saveReceipt({ source: 'sample', clientKey: key, lines: SAMPLE_LINES }) // idempotent
  items = await listItems(h1.id)
  log.afterSave = { count: items.length, first: items[0]?.name, firstDays: items[0]?.daysLeft }

  if (milk) {
    log.expiry = await updateExpiry(milk.id, '2026-10-15')
    log.used = await markUsed(milk.id)
  }
  const chicken = items.find((i) => i.name === 'Chicken breast fillets')
  if (chicken) log.binned = await markBinned(chicken.id)
  items = await listItems(h1.id)
  log.afterStatus = { count: items.length, names: items.map((i) => i.name).slice(0, 4) }
  return NextResponse.json(log)
}
import { randomBytes } from 'node:crypto'
import { cookies } from 'next/headers'
import { eq } from 'drizzle-orm'
import { db, schema } from '@/lib/db'
import type { HouseholdRow } from '@/db/schema'

const COOKIE = 'sl_household'
const ONE_YEAR = 60 * 60 * 24 * 365

async function lookup(): Promise<HouseholdRow | null> {
  const token = (await cookies()).get(COOKIE)?.value
  if (!token || token.length < 32) return null
  const rows = await db().select().from(schema.households).where(eq(schema.households.token, token)).limit(1)
  return rows[0] ?? null
}

/** Read-only: the household for this browser, or null. Safe to call while rendering. */
export async function getHousehold(): Promise<HouseholdRow | null> {
  try {
    return await lookup()
  } catch {
    return null
  }
}

/**
 * For server actions only (they may set cookies). A missing or unknown cookie
 * yields a fresh household rather than an error.
 */
export async function getOrCreateHousehold(): Promise<HouseholdRow> {
  const existing = await lookup()
  if (existing) return existing
  const token = randomBytes(24).toString('base64url') // 32 chars
  const [row] = await db().insert(schema.households).values({ token }).returning()
  ;(await cookies()).set(COOKIE, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    path: '/',
    maxAge: ONE_YEAR,
  })
  return row
}
import { createHash } from 'node:crypto'
import type { FridgeItem } from '@/components/contract'

/** Cache key for dish suggestions: sha1 of the sorted in-stock ids with their expiry dates. */
export function suggestionsKey(items: FridgeItem[]): string {
  const parts = items.map((i) => `${i.id}:${i.expiresOn}`).sort()
  return createHash('sha1').update(parts.join('|')).digest('hex')
}

export type ExtractResult =
  | { ok: true; lines: ExtractedLine[]; notice?: string }
  | { ok: false; error: string }

const UNAVAILABLE = 'The receipt reader is switched off on this deployment (no API credit).'

const MAX_TEXT = 8000

async function runExtract(input: Parameters<typeof extractReceipt>[0]): Promise<ExtractResult> {
  try {
    const lines = await extractReceipt(input)
    return { ok: true, lines }
  } catch (e) {
    if (e instanceof NoReceiptError) {
      return { ok: false, error: 'Could not read a receipt there. Try a clearer photo, or paste the text.' }
    }
    if (isUnavailable(e)) return { ok: false, error: `${UNAVAILABLE} Try the sample receipt, or add items by hand.` }
    console.error('extract', e)
    return { ok: false, error: 'The receipt reader did not answer. Your input is still here; try again.' }
  }
}

export async function extractFromText(text: string): Promise<ExtractResult> {
  const trimmed = (text ?? '').trim()
  if (!trimmed) return { ok: false, error: 'Paste some receipt text first.' }
  if (trimmed.length > MAX_TEXT) {
    return { ok: false, error: `That is over ${MAX_TEXT.toLocaleString()} characters. Trim it down.` }
  }
  return runExtract({ text: trimmed })
}

export async function extractFromImage(formData: FormData): Promise<ExtractResult> {
  const file = formData.get('image')
  if (!(file instanceof File)) return { ok: false, error: 'Pick a photo first.' }
  if (file.size > 5 * 1024 * 1024) return { ok: false, error: 'That image is over 5 MB. Try a smaller photo.' }
  if (!IMAGE_TYPES.includes(file.type as ImageMediaType)) {
    return { ok: false, error: 'Use a JPEG, PNG, WebP or GIF photo.' }
  }
  const data = Buffer.from(await file.arrayBuffer()).toString('base64')
  return runExtract({ image: { data, mediaType: file.type as ImageMediaType } })
}

/** The "Try a sample receipt" button: the real flow over samples/receipt-1.jpg. */
export async function extractSample(): Promise<ExtractResult> {
  try {
    const buf = await readFile(path.join(process.cwd(), 'samples', 'receipt-1.jpg'))
    const lines = await extractReceipt({ image: { data: buf.toString('base64'), mediaType: 'image/jpeg' } })
    return { ok: true, lines }
  } catch (e) {
    if (isUnavailable(e)) {
      // Placeholder until the key has credit: a stored pre-read of the same receipt, labelled.
      return { ok: true, lines: SAMPLE_LINES, notice: `${UNAVAILABLE} Showing a stored pre-read of the sample receipt instead.` }
    }
    if (e instanceof NoReceiptError) return { ok: false, error: 'Could not read the sample receipt. Try again.' }
    console.error('sample', e)
    return { ok: false, error: 'The sample receipt could not be read on this deployment.' }
  }
}

const saveSchema = z.object({
  source: z.enum(['image', 'text', 'sample']),
  clientKey: z.string().uuid(),
  lines: confirmedLinesSchema,
})
export type SaveInput = z.infer<typeof saveSchema>

/**
 * The only write from a receipt. Idempotent per clientKey: a second save of the same
 * extraction inserts nothing. Unticked lines are kept in `extracted` but not as items.
 */
export async function saveReceipt(input: SaveInput): Promise<ActionResult & { saved?: number }> {
  const parsed = saveSchema.safeParse(input)
  if (!parsed.success) return { ok: false, error: 'Check the items: every kept line needs a name and a quantity.' }
  const { source, clientKey, lines } = parsed.data
  const keep = lines.filter((l) => l.isFood)
  if (keep.length === 0) return { ok: false, error: 'Tick at least one item to save.' }
  try {
    const household = await getOrCreateHousehold()
    const existing = await db()
      .select({ id: schema.receipts.id })
      .from(schema.receipts)
      .where(eq(schema.receipts.clientKey, clientKey))
      .limit(1)
    if (existing.length) {
      revalidatePath('/')
      return { ok: true, saved: 0 }
    }
    const receiptId = crypto.randomUUID()
    const today = todayISO()
    await db().batch([
      db().insert(schema.receipts).values({
        id: receiptId,
        householdId: household.id,
        source,
        extracted: lines,
        clientKey,
      }),
      db()
        .insert(schema.items)
        .values(
          keep.map((l) => ({
            householdId: household.id,
            receiptId,
            name: l.name,
            qty: l.qty,
            unit: l.unit || null,
            category: l.category,
            boughtOn: today,
            expiresOn: addDays(today, l.shelfLifeDays),
          })),
        ),
    ])
    revalidatePath('/')
    return { ok: true, saved: keep.length }
  } catch (e) {
    console.error('saveReceipt', e)
    return { ok: false, error: 'Could not save those items. Try again.' }
  }
}

// ---- Dishes -----------------------------------------------------------------

/** On demand: three dishes from the in-stock items, cached on the household against a key of those items. */
export async function refreshDishes(): Promise<ActionResult> {
  try {
    const household = await getOrCreateHousehold()
    const items = await listItems(household.id)
    if (items.length === 0) return { ok: false, error: 'Add something to the fridge first.' }
    const dishes = await suggestDishes(items)
    await db()
      .update(schema.households)
      .set({ suggestions: dishes, suggestionsKey: suggestionsKey(items), suggestionsAt: new Date() })
      .where(eq(schema.households.id, household.id))
    revalidatePath('/')
    return { ok: true }
  } catch (e) {
    if (isUnavailable(e)) return { ok: false, error: 'Dish suggestions are switched off on this deployment (no API credit).' }
    console.error('refreshDishes', e)
    return { ok: false, error: 'Could not get dishes just now. Try again.' }
  }
}

